(* [comment removed for export] *)
Definition tte_ctx (m m1 : mem) (sp s0v s1v rav : word) (P T E lo : Z) (bs : list byte) (E0 : ecv) (g : bool)
    (tj junk : list byte) : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -48) [CB 24 junk]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -24) [C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells rsegs m1 T [CB 8 tj]
  /\ rw_cells rsegs m1 E (ErrCodeCells E0)
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk rsegs m1 lo (bv_unsigned sp + -48)
  /\ bytes_at rsegs m1 P bs
  /\ munch (tte_W lo sp T E) m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

(* [comment removed for export] *)
Definition tte_pure (sp : word) (P T E lo : Z) (bs : list byte) (E0 : ecv) : Prop :=
  ec_ok E0 /\ lo + 80 <= bv_unsigned sp /\ 0xb4000 <= lo /\ ((0 < P /\ P + Z.of_nat (length bs) <= 0x10000) \/ 0x90d70 <= P) /\ P + Z.of_nat (length bs) <= lo
  /\ bv_unsigned sp <= T /\ T + 8 <= 2^64 /\ bv_unsigned sp <= E /\ E + 24 <= 2^64 /\ (T + 8 <= E \/ E + 24 <= T).

Local Ltac open_ctx CTX PURE :=
  destruct CTX as (FRlo & FRhi & TL & EC & HC & XS & ST & WIN & MU & WM & MI);
  destruct PURE as (EOK & LO & IMG & PLO & PHI & TLO & THI & ELO & EHI & TE);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  unfold ErrCodeCells in EC;
  unfold tte_W, G_HTTP_CAT in *.

(* [comment removed for export] *)
Local Ltac finish_tte XS MU2 WM2 :=
  finish; [ (* [comment removed for export] *) cbn [tte_cat]; close_HttpCat_chunks | (* [comment removed for export] *) close_XStatics XS MU2 WM2 ].

