(* [comment removed for export] *)
Lemma tte_b1_print : forall c, 32 <= c < 127 ->
  negb (bv_ltu (Z_to_bv 64 (c + -32)) (Z_to_bv 64 95)) = false.
Proof. intros c Hc. unfold bv_ltu. rewrite !unsigned_lit by lia. apply Bool.negb_false_iff. apply Z.ltb_lt. lia. Qed.
Lemma tte_b1_low : forall c, 0 <= c < 32 ->
  negb (bv_ltu (Z_to_bv 64 (c + -32)) (Z_to_bv 64 95)) = true.
